/**
 * 取り込んだ実データ。
 *
 * areaId は引数で受ける。千代田区・港区を1つのパーティションに入れる方針のため、
 * 区ごとに固定せず設定（AREA_ID）に従わせる。
 */
export function opendataSpots(areaId: AreaId, updatedAt: string): Spot[] {
  const fetchedAtOf = new Map(OPENDATA_SOURCES.map((s) => [s.key, s.fetchedAt]))
  return SEEDS.map((seed) => ({
    spotId: asSpotId(seed.id),
    areaId,
    name: seed.name,
    category: seed.category,
    lat: seed.lat,
    lng: seed.lng,
    address: seed.address,
    attributes: seed.attributes,
    source: seed.source,
    fetchedAt: fetchedAtOf.get(seed.source) ?? '',
    checkinCount: 0,
    updatedAt,
  }))
}
